    <div className="contactGrid">{items.map(({label,value,href,Icon})=><a className="contactCard" href={href} target={href.startsWith('http')?'_blank':undefined} rel={href.startsWith('http')?'noreferrer':undefined} key={label}><span className="contactIcon"><Icon size={21}/></span><div><b>{label}</b><small>{value}</small></div><ArrowUpRight size={16}/></a>)}</div>
